import { isTeamAdmin, isTeamOwner } from "./teams";

export async function addGuests(userId: string, teamId: string, bookingOwnerId: string) {
  const isTeamAdminOrOwner =
    (await isTeamAdmin(userId, teamId)) && (await isTeamOwner(userId, teamId));
  const isOrganizer = bookingOwnerId === userId;
  if (!isTeamAdminOrOwner && !isOrganizer) {
    throw new Error("forbidden");
  }
  return { ok: true };
}

