export function filterGuests(guests: string[], existing: string[]) {
  const blacklisted = (process.env.BLACKLISTED_GUEST_EMAILS ?? "")
    .split(",")
    .map((email) => email.trim().toLowerCase())
    .filter(Boolean);
  return guests.filter((guest) => !existing.includes(guest) && !blacklisted.includes(guest));
}

