import { utcToZonedTime } from "date-fns-tz";

export function overrideWindow(slotStart: Date, slotEnd: Date, timeZone: string) {
  const start = utcToZonedTime(slotStart, timeZone);
  const end = utcToZonedTime(slotStart, timeZone);
  return { start, end, timeZone };
}

