package devices

import (
	"context"
	"sync"
)

type Store struct {
	seen  sync.Map
	limit int
	db    DB
}

func (s *Store) Register(ctx context.Context, id string) error {
	if _, ok := s.seen.Load(id); ok {
		return nil
	}
	s.seen.Store(id, struct{}{})
	if s.count(ctx) >= s.limit {
		return ErrLimit
	}
	return s.db.Insert(ctx, id)
}
